-- HG shared platform migration (schema: claims)
-- Source: HG-Claims/supabase/migrations/20261104150333_enforce_hourly_session.sql
-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `claims`; private schemas renamed private -> claims_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO claims, extensions;

BEGIN;

-- A refresh changes the JWT, but preserves the original Auth session ID.
CREATE OR REPLACE FUNCTION claims_private.session_expires_at() RETURNS timestamptz
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT s.created_at + interval '1 hour'
  FROM auth.sessions s
  WHERE s.id = NULLIF(auth.jwt()->>'session_id', '')::uuid
    AND s.user_id = auth.uid();
$$;
REVOKE ALL ON FUNCTION claims_private.session_expires_at() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION claims_private.session_expires_at() TO authenticated;

CREATE OR REPLACE FUNCTION claims.hg_session_expires_at() RETURNS timestamptz
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
  SELECT claims_private.session_expires_at();
$$;
REVOKE ALL ON FUNCTION claims.hg_session_expires_at() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION claims.hg_session_expires_at() TO authenticated;

CREATE OR REPLACE FUNCTION claims_private.active_user() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT COALESCE(claims_private.session_expires_at() > statement_timestamp(), false)
    AND EXISTS (SELECT 1 FROM claims.profiles WHERE id = auth.uid() AND status = 'ACTIVE');
$$;

-- Use the guarded RPCs for business data. Server-only service grants are separate.
REVOKE ALL ON claims.profiles, claims.claims, claims.claim_attachments,
  claims.signup_invitations, claims.audit_logs FROM anon, authenticated;

DROP POLICY IF EXISTS receipt_active_session ON storage.objects;
CREATE POLICY receipt_active_session ON storage.objects AS RESTRICTIVE
FOR ALL TO authenticated
USING (bucket_id <> 'receipts' OR (SELECT claims_private.active_user()))
WITH CHECK (bucket_id <> 'receipts' OR (SELECT claims_private.active_user()));

-- Receipt previews use authenticated downloads. Don't mint bearer links that
-- would outlive the session or bypass claim ownership checks when opened.
DROP POLICY IF EXISTS receipt_no_signed_urls ON storage.objects;
CREATE POLICY receipt_no_signed_urls ON storage.objects AS RESTRICTIVE
FOR ALL TO authenticated
USING (bucket_id <> 'receipts' OR NOT storage.allow_any_operation(
  ARRAY['object.sign', 'object.sign_many', 'object.sign_upload_url']
))
WITH CHECK (bucket_id <> 'receipts' OR NOT storage.allow_any_operation(
  ARRAY['object.sign', 'object.sign_many', 'object.sign_upload_url']
));

CREATE OR REPLACE FUNCTION claims_private.can_read_receipt(path text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT claims_private.active_user() AND (
    split_part(path, '/', 1) = auth.uid()::text
    OR EXISTS (
      SELECT 1 FROM claims.claim_attachments a
      JOIN claims.claims c ON c.id = a.claim_id
      WHERE a.storage_path = path AND (
        c.submitted_by_user_id = auth.uid() OR c.claimant_id = auth.uid()
        OR (c.status <> 'DRAFT' AND (
          claims_private.has_role('FINANCE_OFFICER') OR claims_private.has_role('SYSTEM_ADMIN')
        ))
      )
    )
  );
$$;

-- The frozen payment snapshot also contains account numbers and identifiers.
CREATE OR REPLACE FUNCTION claims_private.redact_workspace_snapshot(p_snapshot jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  result jsonb := p_snapshot;
  caller uuid := auth.uid();
  privileged boolean := claims_private.has_role('FINANCE_OFFICER') OR claims_private.has_role('SYSTEM_ADMIN');
  profiles jsonb;
  claims jsonb;
BEGIN
  IF NOT claims_private.active_user() THEN
    RAISE EXCEPTION 'Active account required' USING ERRCODE = '42501';
  END IF;

  IF result ? 'profiles' THEN
    SELECT COALESCE(jsonb_agg(
      CASE WHEN privileged OR p->>'id' = caller::text OR p->>'created_by_user_id' = caller::text
        THEN p
        ELSE p - 'bank_name' - 'bank_code' - 'bank_account_holder_name'
          - 'bank_account_number' - 'beneficiary_new_ic' - 'beneficiary_old_ic'
          - 'beneficiary_business_reg' - 'beneficiary_others' - 'beneficiary_address'
          - 'phone' - 'email'
      END
    ), '[]'::jsonb) INTO profiles
    FROM jsonb_array_elements(result->'profiles') p;
    result := jsonb_set(result, '{profiles}', profiles);
  END IF;

  -- Historical workflows may allow a non-finance reviewer to read a claim.
  -- Such review does not require the claimant's payment identifiers.
  IF result ? 'claims' AND NOT privileged THEN
    SELECT COALESCE(jsonb_agg(
      CASE WHEN c->>'claimant_id' = caller::text OR c->>'submitted_by_user_id' = caller::text
        THEN c
        ELSE c - 'bank_name' - 'bank_code' - 'bank_account_holder_name'
          - 'bank_account_number' - 'beneficiary_new_ic' - 'beneficiary_old_ic'
          - 'beneficiary_business_reg' - 'beneficiary_others' - 'beneficiary_address' - 'approved_snapshot'
      END
    ), '[]'::jsonb) INTO claims
    FROM jsonb_array_elements(result->'claims') c;
    result := jsonb_set(result, '{claims}', claims);
  END IF;

  RETURN result;
END $$;

COMMIT;
